head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
scwin.onpageload = function() {
	scwin.data1 = [
		"(가)다/라다", "A", 1,
		"(가)다/라다", "A", 2,
		"(가)다/라다", "A", 3,
		"가", "B", 4,
		"가", "C", 5,
		"나", "A", 6,
		"나", "B", 7,
		"나", "C", 8,
		"다", "A", 9,
		"다", "B", 10,
		"다", "C", 11,
		"가", "A", 12,
		"가", "B", 13,
		"가", "C", 14,
		"나", "A", 15,
		"나", "B", 16,
		"나", "C", 17,
		"다", "A", 18,
		"다", "B", 19,
		"다", "C", 20,
		"가", "A", 21,
		"가", "B", 22,
		"가", "C", 23,
		"나", "A", 24,
		"나", "B", 25,
		"나", "C", 26,
		"다", "A", 27,
		"다", "B", 28,
		"다", "C", 29,
		"가", "A", 30
	];
	dataList1.setData(scwin.data1.slice(0));
};
scwin.trigger10_onclick = function(e) {
	data = dataList1.getMatchedJSON("col1", "가");
};
scwin.fireDbClick = function(node) {
	if (document.createEventObject) {
		node.fireEvent('ondblclick');
	} else if (document.createEvent) {
		var evt = document.createEvent('MouseEvents');
		evt.initEvent('dblclick', true, false);
		node.dispatchEvent(evt);
	} else if (typeof node.ondblclick == 'function') {
		node.ondblclick();
	}
};
scwin.Dbclick = function(id) {
	var el = scwin.__getDom($p.id + id);
	scwin.fireDbClick(el);
};
scwin.checkSorting = function() {
	var k = 0;
	for (var i = 30; i >= 0; i--) {
		if (i == 19) {
			grid1.setBottomRowIndex(20);
			k = 0;
		}
		if (i == 10) {
			grid1.setBottomRowIndex(30);
			k = 0;
		}
		if (scwin.__getDom($p.id + "grid1_cell_" + k + "_2").textContent == i) {
			k++;
			return true;
		} else {
			return false;
		}
	}
};
scwin.checkData = function(data) {
	for (var i = 0; i < data.length; i++) {
		if (data[i].col1 == "가") {
			return true;
		} else {
			return false;
		}
	}
};
scwin.setVal = function() {
	return scwin.checkData(data);
};
scwin.onpageload2 = function() {
	scwin.onpageload();
	window.data = undefined;
};
